import numpy as np

from traminex.events import EventSequence, events_transition_degrees


def test_events_weighted_degrees():
    events = EventSequence(
        id=["p1", "p1", "p2", "p2", "p2"],
        time=np.array([1, 2, 1, 3, 4]),
        label=["A", "B", "A", "B", "C"],
    )
    labs, indeg_u, outdeg_u = events_transition_degrees(events, normalize=False)
    labs, indeg_w, outdeg_w = events_transition_degrees(
        events, normalize=False, id_weights={"p2": 2.0}
    )
    # Weighted outdegree for labels generated by p2 should be larger or equal
    assert outdeg_w.sum() >= outdeg_u.sum()
